import{_ as p,a0 as r,w as i,s as u,ao as d,I as n,x as o,a1 as e,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"埃隆·马斯克认为推特的算法应该开源 | LCTT x X-CMD","titleTemplate":false,"description":"埃隆·马斯克认为推特的算法应该开源 | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"埃隆·马斯克认为推特的算法应该开源 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"埃隆·马斯克认为推特的算法应该开源 | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20220415 Elon Musk Believes Twitter Algorithm Should Be Open-Source","title":"埃隆·马斯克认为推特的算法应该开源","tag":"202204","desc":""},"relativePath":"202204/20220415 Elon Musk Believes Twitter Algorithm Should Be Open-Source.md","filePath":"[post].md"}'),a={name:"202204/20220415 Elon Musk Believes Twitter Algorithm Should Be Open-Source.md"};function m(f,t,T,k,g,x){const s=r("Link");return i(),u("div",null,[t[20]||(t[20]=d('<h1 id="埃隆·马斯克认为推特的算法应该开源" tabindex="-1">埃隆·马斯克认为推特的算法应该开源 <a class="header-anchor" href="#埃隆·马斯克认为推特的算法应该开源" aria-label="Permalink to “埃隆·马斯克认为推特的算法应该开源”">​</a></h1><blockquote><p>埃隆·马斯克希望推特开源他们的算法。这会促进言论自由吗？以下是他的说法。</p></blockquote><p><img src="https://news.itsfoss.com/wp-content/uploads/2022/04/elon-musk-twitter-algorithm-opensource.jpg" alt=""></p><p>没错，埃隆·马斯克又搞了一个大新闻，这已经算是他的日常操作了。</p><p>然而，这一次的新闻非常有趣。他提出了要以大约 <strong>430 亿美元</strong> 收购推特。</p><p>从技术上讲，他的报价远远超过了市场价格，这也就是为什么许多媒体称他这是在试图“恶意收购”。</p><p>考虑到这个激进的报价，我们还不确定这次收购是否会成功。不过，在一次 TED 演讲中，埃隆·马斯克还分享了他对于推特应该如何推动言论自由的一些想法。</p><h3 id="推特的算法应该开源" tabindex="-1">推特的算法应该开源 <a class="header-anchor" href="#推特的算法应该开源" aria-label="Permalink to “推特的算法应该开源”">​</a></h3><p>埃隆·马斯克认为，推特应该将算法开源，以促进平台的透明度。</p><p>当然，推特作为一个平台，目前仍在爆炸式发展，很难预测。推特团队在某些事情上也会采取果断行动，不管用户认为它是否正确。</p><p>虽然推特的内部决定在纸面上看起来很好，但这种没有透明度的大规模平台总是会存在问题的。</p><p>因此，埃隆·马斯克有一个观点：无论你是否认同或相信推特的决定，透明/开源只会有助于加强现有的价值观。</p><p>嗯，难怪我们喜欢开源。</p><p>这里引用他的原话：</p><blockquote><p>“因此，我认为推特应该做的事情之一就是开源它的算法，所有推文的修改都应该是透明的，任何人都可以看到这个修改，哪怕是加粗一段文字或是取消加粗它。这样一来，幕后操纵将不复存在，无论是算法还是人工。”</p></blockquote>',15)),n("p",null,[t[2]||(t[2]=o("另一方面，当我们把推特当作一个某种程度上的开源平台来谈论时，我不由自主地想到了 ",-1)),e(s,{href:"https://joinmastodon.org/"},{default:l(()=>[...t[0]||(t[0]=[o("Mastodon",-1)])]),_:1}),t[3]||(t[3]=o("。你也可以在 ",-1)),e(s,{href:"https://mastodon.social/@itsfoss"},{default:l(()=>[...t[1]||(t[1]=[o("Mastodon",-1)])]),_:1}),t[4]||(t[4]=o(" 上找到我们，如果你还没有用过它的话。",-1))]),t[21]||(t[21]=n("p",null,"诚然，推特有很大的增长潜力，无论好坏，它都在不断扩张。但是，开源理念能否帮助这个平台？我个人认为可以，但这是一个巨大的变革，不能指望一夜之间就能实现。",-1)),t[22]||(t[22]=n("p",null,"当然，即使埃隆·马斯克成功地收购了推特，也没有人能够预测他会对推特做什么。说实话，他就像任何复杂算法一样不可预测。",-1)),t[23]||(t[23]=n("p",null,"那么，你是如何看待这个新闻的呢？你相信埃隆·马斯克说的话吗？欢迎在下面的评论中分享你的想法。",-1)),t[24]||(t[24]=n("hr",null,null,-1)),n("p",null,[t[6]||(t[6]=o("via: ",-1)),e(s,{href:"https://news.itsfoss.com/elon-musk-twitter-open-source/"},{default:l(()=>[...t[5]||(t[5]=[o("https://news.itsfoss.com/elon-musk-twitter-open-source/",-1)])]),_:1})]),n("p",null,[t[11]||(t[11]=o("作者：",-1)),e(s,{href:"https://news.itsfoss.com/author/ankush/"},{default:l(()=>[...t[7]||(t[7]=[o("Ankush Das",-1)])]),_:1}),t[12]||(t[12]=o(" 选题：",-1)),e(s,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[8]||(t[8]=[o("lujun9972",-1)])]),_:1}),t[13]||(t[13]=o(" 译者：",-1)),e(s,{href:"https://github.com/lkxed"},{default:l(()=>[...t[9]||(t[9]=[o("lkxed",-1)])]),_:1}),t[14]||(t[14]=o(" 校对：",-1)),e(s,{href:"https://github.com/wxy"},{default:l(()=>[...t[10]||(t[10]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[17]||(t[17]=o("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[15]||(t[15]=[o("LCTT",-1)])]),_:1}),t[18]||(t[18]=o(" 原创编译，",-1)),e(s,{href:"https://linux.cn/"},{default:l(()=>[...t[16]||(t[16]=[o("Linux中国",-1)])]),_:1}),t[19]||(t[19]=o(" 荣誉推出",-1))])])}const b=p(a,[["render",m]]);export{S as __pageData,b as default};
